function renderAffiliateDashboard(){
 let a=getAffiliate(session.aff);const root=$('affiliatePanel');if(a&&['deleted','disabled','pending'].includes(activeStatus(a)))a=null;if(!a){$('affHeadRight').innerHTML='';root.innerHTML=loginForm('aff');bindLogin('aff');return}
 const status=activeStatus(a);$('affHeadRight').innerHTML=badge(status)+' <button class="secondary" id="affLogout">Keluar</button>';$('affLogout').onclick=logout;const orders=db.orders;const comm=db.commissions;const bal=affBalance(a.id);const ready=bal.ready;const pending=bal.pending;const paid=bal.paid;const correction=comm.filter(c=>c.status==='reversed').reduce((n,c)=>n+(Number(c.correctionOutstanding)||0),0);
 const referralUrl=baseUrl()+'?ref='+encodeURIComponent(a.code);
 root.innerHTML=`<div class="stats"><div class="stat"><div class="label">Pesanan teratribusi</div><div class="value">${orders.length}</div></div><div class="stat"><div class="label">Komisi tertunda</div><div class="value">${money(pending)}</div></div><div class="stat"><div class="label">Siap dibayar</div><div class="value">${money(ready)}</div></div><div class="stat"><div class="label">Sudah dibayar</div><div class="value">${money(paid)}</div></div></div>
 <div class="panel"><div class="panel-head"><div><h3>Link referral</h3><div class="muted">Berlaku selama sesi browser pelanggan.</div></div>${badge(status)}</div><div class="inline"><input id="referralLink" value="${esc(referralUrl)}" readonly style="flex:1;min-width:180px;padding:10px;border:1px solid var(--line);border-radius:9px"><button id="copyReferral">Salin link</button></div><div class="muted" style="margin-top:8px">Kode: ${esc(a.code)} · Aktif sampai: ${esc(a.endDate||'-')} · Komisi Anda: ${esc(affiliateCommLabel(a))}</div></div>
 <div class="panel"><div class="panel-head"><div><h3>Riwayat pesanan</h3><div class="muted">Hanya pesanan yang dikaitkan dengan akun ini. Nomor HP dan alamat pelanggan tidak ditampilkan.</div></div></div>${orders.length?`<div class="table-wrap"><table><thead><tr><th>No. pesanan</th><th>Pelanggan</th><th>Ringkasan</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.orderNo)}</td><td>${esc(o.customerName)}</td><td><div class="rowline" style="flex-wrap:nowrap;gap:8px">${orderThumb(o)}<div>${esc(o.productName)}<br><span class="muted">${esc(itemsText(o))}</span></div></div></td><td>${money(o.total)}</td><td>${badge(o.status)}</td><td>${o.status==='awaiting_payment'?`<button class="success" data-claim="${o.id}">Konfirmasi bayar</button>`:o.status==='payment_claimed'?'<span class="muted">Menunggu admin</span>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada pesanan yang teratribusi.</div>'}</div>
 <div class="panel"><div class="panel-head"><div><h3>Riwayat komisi</h3><div class="muted">Saldo siap dibayar hanya mencakup komisi yang disetujui admin.</div></div></div>${comm.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pesanan</th><th>Nilai</th><th>Status</th><th>Catatan</th></tr></thead><tbody>${comm.map(c=>`<tr><td>${new Date(c.createdAt).toLocaleDateString('id-ID')}</td><td>${esc(c.orderNo||'-')}</td><td>${money(c.amount)}</td><td>${badge(c.status)}</td><td>${esc(c.note||'-')}${c.status==='approved'&&paidOf(c)>0?'<br><span class="muted">Terbayar '+money(paidOf(c))+' dari '+money(c.amount)+'</span>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada komisi.</div>'}</div>
 ${correction?`<div class="notice">Total koreksi tercatat: ${money(correction)}. Koreksi dapat mengurangi komisi berikutnya.</div>`:''}`;
 root.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{const o=db.orders.find(x=>x.id===b.dataset.claim);if(!o||!confirm('Konfirmasi bahwa pelanggan sudah membayar pesanan '+o.orderNo+'? Admin akan memverifikasinya.'))return;call('claim_payment',{p_order_id:o.id})});
 $('copyReferral').onclick=()=>copyText(referralUrl,'Link referral disalin.');
}

