function setAdminView(view){activeAdminView=view;document.querySelectorAll('#adminTabs button').forEach(b=>b.classList.toggle('active',b.dataset.adminview===view));renderAdmin()}
document.querySelectorAll('#adminTabs button').forEach(b=>b.addEventListener('click',()=>setAdminView(b.dataset.adminview)));
function renderAdmin(){const root=$('adminContent');$('adminTabs').classList.toggle('hidden',!session.admin);$('adminHead').innerHTML=session.admin?'<button class="secondary" id="admLogout">Keluar</button>':'';if(!session.admin){root.innerHTML=loginForm('admin');bindLogin('admin');return}$('admLogout').onclick=logout;const active=db.affiliates.filter(a=>activeStatus(a)==='active').length;const ready=db.commissions.reduce((n,c)=>n+remainOf(c),0);
 if(activeAdminView==='overview'){root.innerHTML=`<div class="stats"><div class="stat"><div class="label">Produk</div><div class="value">${db.products.length}</div></div><div class="stat"><div class="label">Affiliate aktif</div><div class="value">${active}</div><div class="sub">Masa aktif 6 bulan</div></div><div class="stat"><div class="label">Pesanan</div><div class="value">${db.orders.length}</div></div><div class="stat"><div class="label">Komisi siap dibayar</div><div class="value">${money(ready)}</div></div></div><div class="panel"><h3>Ringkasan alur kerja</h3><p class="muted">1. Kelola produk dan stok. 2. Tambah affiliate dan atur komisi. 3. Konfirmasi pembayaran pelanggan setelah memeriksa stok. 4. Setujui komisi secara manual. 5. Transfer komisi dan catat pembayaran.</p><div class="notice">Jika pembayaran diterima tetapi stok tidak cukup, sistem menandai pesanan untuk penyelesaian admin. Lakukan refund bila diperlukan.</div></div><div class="panel"><h3>Aktivitas terbaru</h3>${db.audit.slice(0,8).map(l=>`<div class="affiliate-card"><div class="grow"><strong>${esc(l.action)}</strong><small>${esc(l.detail)} · ${new Date(l.date).toLocaleString('id-ID')}</small></div></div>`).join('')||'<div class="empty">Belum ada aktivitas.</div>'}</div>`}
 else if(activeAdminView==='products')renderProductsAdmin(root);
 else if(activeAdminView==='affiliates')renderAffiliatesAdmin(root);
 else if(activeAdminView==='orders')renderOrdersAdmin(root);
 else if(activeAdminView==='commissions')renderCommissionsAdmin(root);
 else if(activeAdminView==='payments')renderPaymentsAdmin(root);
 else if(activeAdminView==='saleslink')renderSalesLinkAdmin(root);
 else if(activeAdminView==='settings')renderSettingsAdmin(root);
}

/* --- Produk --- */
function renderProductsAdmin(root){root.innerHTML=`<div class="panel-head"><div><h3>Produk dan stok</h3><div class="muted">Total stok dijumlahkan dari seluruh variasi produk.</div></div><button id="addProduct">+ Tambah produk</button></div>${db.products.length?`<div class="table-wrap"><table><thead><tr><th>Produk</th><th>Harga</th><th>Variasi / stok</th><th>Komisi</th><th>Aksi</th></tr></thead><tbody>${db.products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><span class="muted">${esc(p.category)} · ${esc(p.type)}</span></td><td>${money(p.price)}</td><td>${(p.variants||[]).map(v=>`${esc([v.group,v.type,v.color,v.size].filter(Boolean).join(' / '))}: <b>${v.stock}</b>`).join('<br>')}<br><b>Total ${stock(p)} pcs</b></td><td>${p.commissionMode==='default'?'Default':p.commissionMode==='fixed'?money(p.commissionValue):p.commissionValue+'%'}</td><td><div class="actions"><button class="secondary" data-editproduct="${p.id}">Edit</button><button class="danger" data-delproduct="${p.id}">Hapus</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada produk.</div>'}`;
 $('addProduct').onclick=()=>openProductForm();root.querySelectorAll('[data-editproduct]').forEach(b=>b.onclick=()=>openProductForm(b.dataset.editproduct));root.querySelectorAll('[data-delproduct]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.delproduct));
}
function openProductForm(id=''){const p=id?getProduct(id):null;$('productForm').reset();$('productId').value=p?.id||'';$('productModalTitle').textContent=p?'Edit produk':'Tambah produk';$('pName').value=p?.name||'';$('pCategory').value=p?.category||'';$('pPrice').value=p?.price??135000;$('pType').value=p?.type||'';$('pDesc').value=p?.description||'';$('pCommissionMode').value=p?.commissionMode||'default';$('pCommissionValue').value=p?.commissionValue||0;$('pImageUrl').value='';productImages=productImgs(p).slice();renderImageList();variantDraft=p?(p.variants||[]).map(v=>({...v})):[{type:'Boxy Fit',color:'Hitam',size:'M',stock:0}];editGroup=null;renderVariantEditor();$('productStatus').textContent='';$('productModal').classList.add('show')}
const grpKey=v=>(v.group||'').trim();
function groupsOf(){const o=[];variantDraft.forEach(v=>{const g=grpKey(v);if(!o.includes(g))o.push(g)});return o}
function addVariantTo(g){const same=variantDraft.filter(v=>grpKey(v)===g),base=same[same.length-1];variantDraft.push({group:g,type:(base&&base.type)||$('pType').value||'',color:'',size:'',stock:0});editGroup=g;renderVariantEditor()}
function renderVariantEditor(){
 let gs=groupsOf();if(!gs.length)gs=[''];
 if(editGroup===null||!gs.includes(editGroup))editGroup=gs[0];
 const cnt=g=>variantDraft.filter(v=>grpKey(v)===g).length;
 const tabs='<div class="vtabs etabs">'+gs.map((g,k)=>'<button type="button" class="vtab'+(g===editGroup?' on':'')+'" data-etab="'+k+'">'+esc(g||'Tanpa kelompok')+'<span class="tbadge" style="display:inline-grid">'+cnt(g)+'</span></button>').join('')+'<button type="button" class="vtab add" id="addGroupBtn">+ Kelompok</button></div>';
 const head='<div class="egroup-head"><div class="field" style="flex:1;min-width:0"><label>Nama kelompok (teks bebas, kosongkan = tanpa kelompok)</label><input id="grpName" value="'+esc(editGroup)+'" placeholder="mis. Ukuran M" autocomplete="off"></div><button type="button" class="danger" id="delGroupBtn" style="flex:0 0 auto">Hapus kelompok</button></div>';
 const cards=variantDraft.map((v,i)=>grpKey(v)!==editGroup?'':`<div class="variant-editor"><div class="variant-row" data-vi="${i}"><div><label>Varian 1</label><input data-v="type" value="${esc(v.type||'')}" placeholder="mis. Boxy Fit" autocomplete="off"></div><div><label>Varian 2</label><input data-v="color" value="${esc(v.color||'')}" placeholder="mis. Hitam" autocomplete="off"></div><div class="vphoto"><label>Foto</label><div class="vphoto-row"><label class="vphoto-btn"><input type="file" accept="image/*" data-vimg="${i}" hidden>${v.image?`<img src="${esc(v.image)}" alt="">`:''}<span>${v.image?'Ganti':'+ Unggah'}</span></label>${v.image?`<button type="button" class="danger vphoto-del" data-vimgdel="${i}" aria-label="Hapus foto">✕</button>`:''}</div></div><div><label>Stok</label><input data-v="stock" type="number" min="0" value="${Number(v.stock)||0}"></div><button type="button" class="danger remove-v" data-remove="${i}">Hapus</button></div></div>`).join('');
 const add='<button type="button" class="secondary" id="addInGroupBtn" style="width:100%;margin-top:4px">+ Tambah variasi'+(editGroup?' di '+esc(editGroup):'')+'</button>';
 const ed=$('variantEditor');ed.innerHTML=tabs+head+cards+add;
 ed.querySelectorAll('[data-etab]').forEach(b=>b.onclick=()=>{editGroup=gs[Number(b.dataset.etab)];renderVariantEditor()});
 $('addGroupBtn').onclick=()=>{let n=gs.length+1,nm='Kelompok '+n;while(gs.includes(nm))nm='Kelompok '+(++n);addVariantTo(nm)};
 $('addInGroupBtn').onclick=()=>addVariantTo(editGroup);
 $('grpName').addEventListener('change',e=>{const nv=e.target.value.trim(),old=editGroup;if(nv===old)return;variantDraft.forEach(v=>{if(grpKey(v)===old)v.group=nv});editGroup=nv;renderVariantEditor()});
 $('delGroupBtn').onclick=()=>{const n=cnt(editGroup);if(n&&!confirm('Hapus kelompok "'+(editGroup||'Tanpa kelompok')+'" beserta '+n+' variasinya?'))return;variantDraft=variantDraft.filter(v=>grpKey(v)!==editGroup);editGroup=null;renderVariantEditor()};
 ed.querySelectorAll('[data-v]').forEach(el=>el.addEventListener('input',()=>{const row=el.closest('[data-vi]');const i=Number(row.dataset.vi),key=el.dataset.v;variantDraft[i][key]=key==='stock'?Math.max(0,Number(el.value)||0):el.value}));
 ed.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{variantDraft.splice(Number(b.dataset.remove),1);renderVariantEditor()});
 ed.querySelectorAll('[data-vimg]').forEach(el=>el.addEventListener('change',async()=>{const f=el.files?.[0];if(!f||!f.type.startsWith('image/'))return;try{variantDraft[Number(el.dataset.vimg)].image=await compressImage(f,1600);renderVariantEditor()}catch(e){alert('Gagal memproses gambar.')}}));
 ed.querySelectorAll('[data-vimgdel]').forEach(b=>b.onclick=()=>{variantDraft[Number(b.dataset.vimgdel)].image='';renderVariantEditor()})}
$('addVariant').onclick=()=>addVariantTo(editGroup===null?(groupsOf()[0]??''):editGroup);
$('cancelProduct').onclick=()=>{$('productForm').reset();variantDraft=[];$('productModal').classList.remove('show')};
$('pImage').addEventListener('change',async e=>{const fl=[...(e.target.files||[])];e.target.value='';await addProductImages(fl,1200)});
function compressImage(file,max=1600){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const sc=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*sc);c.height=Math.round(im.height*sc);const cx=c.getContext('2d');cx.imageSmoothingEnabled=true;cx.imageSmoothingQuality='high';cx.drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.88))};im.src=r.result};r.readAsDataURL(file)})}
$('productForm').addEventListener('submit',async e=>{e.preventDefault();const st=$('productStatus');st.style.color='var(--red)';const name=$('pName').value.trim(),category=$('pCategory').value.trim(),price=Number($('pPrice').value),type=$('pType').value.trim();if(!name||!category||!type||price<0||!variantDraft.length){st.textContent='Lengkapi data produk dan minimal satu variasi.';return}const imgs0=productImages.slice();const imgUrl=$('pImageUrl').value.trim();if(imgUrl&&imgs0.length<MAX_IMG)imgs0.push(imgUrl);if(!imgs0.length){st.textContent='Unggah minimal 1 foto produk (maksimal '+MAX_IMG+').';return}for(const v of variantDraft){if(![v.type,v.color].some(x=>String(x||'').trim())){st.textContent='Isi minimal Varian 1 atau Varian 2 pada setiap variasi.';return}}
 const btn=$('productForm').querySelector('button[type=submit]');btn.disabled=true;st.style.color='var(--green)';st.textContent='Menyimpan...';
 try{const id=$('productId').value;const imgs=[];for(const s of imgs0)imgs.push(s.startsWith('data:')?await uploadImage(s,'products'):s);
  const row={name,category,price,type,description:$('pDesc').value.trim(),image_url:imgs[0]||'',image_urls:imgs,commission_mode:$('pCommissionMode').value,commission_value:Math.max(0,Number($('pCommissionValue').value)||0)};let pid=id;
  if(id){const {error}=await sb.from('products').update(row).eq('id',id);if(error)throw error}else{const {data,error}=await sb.from('products').insert(row).select('id').single();if(error)throw error;pid=data.id}
  if(id){const keep=variantDraft.filter(v=>v.id).map(v=>v.id);const gone=(getProduct(id)?.variants||[]).map(v=>v.id).filter(x=>!keep.includes(x));if(gone.length){const {error}=await sb.from('product_variants').delete().in('id',gone);if(error)throw error}}
  for(let i=0;i<variantDraft.length;i++){const v=variantDraft[i];let vi=v.image||'';if(vi.startsWith('data:'))vi=await uploadImage(vi,'variants');const r={product_id:pid,group_name:(v.group||'').trim(),type:(v.type||'').trim(),color:(v.color||'').trim(),size:'',image_url:vi,stock:Math.max(0,Number(v.stock)||0),sort_order:i};const res=v.id?await sb.from('product_variants').update(r).eq('id',v.id):await sb.from('product_variants').insert(r);if(res.error)throw res.error}
  await adminLog(id?'Produk diperbarui':'Produk ditambahkan',name);$('productModal').classList.remove('show');await refresh()}
 catch(err){st.style.color='var(--red)';st.textContent='Gagal menyimpan: '+(err.message||err)}finally{btn.disabled=false}});
async function deleteProduct(id){const p=getProduct(id);if(!p)return;const open=db.orders.filter(o=>o.productId===id&&['awaiting_payment','payment_claimed'].includes(o.status));if(open.length)return alert('Ada '+open.length+' pesanan yang belum selesai untuk produk ini ('+open.map(o=>o.orderNo).join(', ')+'). Batalkan atau selesaikan pesanan itu dulu.');const n=db.orders.filter(o=>o.productId===id).length;if(!confirm('Hapus produk "'+p.name+'" secara permanen?'+(n?'\n\n'+n+' pesanan lama tetap tersimpan sebagai riwayat.':'')))return;const {error}=await sb.from('products').delete().eq('id',id);if(error)return alert(error.message);await adminLog('Produk dihapus',p.name);await refresh()}

/* --- Affiliate --- */
function renderAffiliatesAdmin(root){root.innerHTML=`<div class="panel-head"><div><h3>Manajemen affiliate</h3><div class="muted">Buat username dan password untuk affiliate di sini, lalu berikan keduanya kepada affiliate. Affiliate login lewat tab Dashboard affiliate. Untuk mengganti password, tekan Edit dan isi password baru.</div></div><button id="addAffiliate">+ Tambah affiliate</button></div><div class="toolbar"><input id="affiliateSearch" placeholder="Cari nama, email, kode..."><select id="affiliateStatusFilter"><option value="">Semua status</option><option value="active">Aktif</option><option value="pending">Menunggu</option><option value="expired">Kedaluwarsa</option><option value="disabled">Dinonaktifkan</option><option value="deleted">Dihapus</option></select></div><div id="affiliateAdminList"></div>`;
 const draw=()=>{const q=$('affiliateSearch').value.toLowerCase(),f=$('affiliateStatusFilter').value;const list=db.affiliates.filter(a=>[a.name,a.username,a.code].join(' ').toLowerCase().includes(q)&&(!f||activeStatus(a)===f));$('affiliateAdminList').innerHTML=list.length?list.map(a=>`<div class="affiliate-card"><div class="avatar">${esc(a.name.slice(0,1).toUpperCase())}</div><div class="grow"><strong>${esc(a.name)} · ${esc(a.code)}</strong><small>Username: <b>${esc(a.username||'-')}</b> · Mulai: ${esc(a.startDate||'-')} · Berakhir: ${esc(a.endDate||'-')}</small><div style="margin-top:5px">${badge(activeStatus(a))} <span class="badge blue">Komisi: ${esc(affiliateCommLabel(a))}</span> <span class="badge ${a.userId?'green':'amber'}">${a.userId?'Akun login aktif':'Belum ada akun login'}</span></div></div><div class="actions">${activeStatus(a)==='pending'?`<button class="success" data-approve="${a.id}">Setujui</button>`:''}${activeStatus(a)!=='deleted'?`<button class="success" data-editaffiliate="${a.id}">Atur komisi</button><button class="secondary" data-editaffiliate="${a.id}">Edit</button><button class="secondary" data-toggle="${a.id}">${a.status==='disabled'?'Aktifkan':'Nonaktifkan'}</button><button class="danger" data-deleteaffiliate="${a.id}">Hapus</button>`:''}</div></div>`).join(''):'<div class="empty">Tidak ada affiliate untuk filter ini.</div>';
 const L=$('affiliateAdminList');
 L.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{const a=getAffiliate(b.dataset.approve);const {error}=await sb.from('affiliates').update({status:'active',start_date:today(),end_date:plusMonths(today(),6)}).eq('id',a.id);if(error)return alert(error.message);await adminLog('Affiliate disetujui',a.name);await refresh()});
 L.querySelectorAll('[data-editaffiliate]').forEach(b=>b.onclick=()=>openAffiliateForm(b.dataset.editaffiliate));
 L.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{const a=getAffiliate(b.dataset.toggle);if(!a)return;const upd={status:a.status==='disabled'?'active':'disabled'};if(upd.status==='active'&&(!a.endDate||a.endDate<today())){upd.start_date=today();upd.end_date=plusMonths(today(),6)}const {error}=await sb.from('affiliates').update(upd).eq('id',a.id);if(error)return alert(error.message);await adminLog('Status affiliate diubah',a.name+' → '+upd.status);await refresh()});
 L.querySelectorAll('[data-deleteaffiliate]').forEach(b=>b.onclick=()=>deleteAffiliate(b.dataset.deleteaffiliate));
 };
 $('addAffiliate').onclick=()=>openAffiliateForm();$('affiliateSearch').addEventListener('input',draw);$('affiliateStatusFilter').addEventListener('change',draw);draw();
}
function openAffiliateForm(id=''){const a=id?getAffiliate(id):null;$('affiliateForm').reset();$('aId').value=a?.id||'';$('affiliateModalTitle').textContent=a?'Edit affiliate':'Tambah affiliate';$('aName').value=a?.name||'';$('aEmail').value=a?.username||'';$('aEmail').readOnly=!!a;$('aEmail').closest('.field').querySelector('label').innerHTML=a?'Username login <span class="muted">(tidak bisa diubah setelah dibuat)</span>':'Username login * <span class="muted">(huruf kecil/angka, tanpa spasi)</span>';$('aPass').value='';$('aPass').required=!a;$('aPass').placeholder=a?'Kosongkan jika tidak diganti':'min. 6 karakter';$('aCode').value=a?.code||'KBR'+Math.random().toString(36).slice(2,6).toUpperCase();$('aStatus').value=a?.status||'active';$('aStart').value=a?.startDate||today();$('aEnd').value=a?.endDate||plusMonths($('aStart').value,6);$('aCommMode').value=a?.commissionMode||'default';$('aCommValue').value=a?.commissionValue||0;syncCommInput();$('affiliateFormStatus').textContent='';$('affiliateModal').classList.add('show')}
function syncCommInput(){const d=$('aCommMode').value==='default';$('aCommValue').disabled=d;if(d)$('aCommValue').value=0}
$('aCommMode').addEventListener('change',syncCommInput);
$('setSixMonths').onclick=()=>{$('aEnd').value=plusMonths($('aStart').value||today(),6)};
$('aStart').addEventListener('change',()=>{if(!$('aId').value)$('aEnd').value=plusMonths($('aStart').value,6)});
$('affiliateForm').addEventListener('submit',async e=>{e.preventDefault();const st=$('affiliateFormStatus');st.style.color='var(--red)';
 const id=$('aId').value,name=$('aName').value.trim(),username=$('aEmail').value.trim().toLowerCase(),code=$('aCode').value.trim().toUpperCase(),pass=$('aPass').value;
 if(!id&&!/^[a-z0-9._-]{3,30}$/.test(username))return st.textContent='Username 3-30 karakter: huruf kecil, angka, titik, strip, atau garis bawah (tanpa spasi).';
 if(db.affiliates.some(a=>a.code.toUpperCase()===code&&a.id!==id&&!a.deletedAt))return st.textContent='Kode referral sudah digunakan.';
 if(!id&&db.affiliates.some(a=>(a.username||'')===username))return st.textContent='Username sudah dipakai.';
 if(!id&&pass.length<6)return st.textContent='Password minimal 6 karakter.';
 if(id&&pass&&pass.length<6)return st.textContent='Password baru minimal 6 karakter.';
 const mode=$('aCommMode').value;const val=mode==='default'?0:Math.max(0,Number($('aCommValue').value)||0);if(mode==='percent'&&val>100)return st.textContent='Persentase komisi maksimal 100%.';
 const row={name,code,status:$('aStatus').value,start_date:$('aStart').value,end_date:$('aEnd').value,commission_mode:mode,commission_value:val};
 const btn=$('affiliateForm').querySelector('button[type=submit]');btn.disabled=true;st.style.color='var(--green)';st.textContent='Menyimpan...';
 try{
  if(id){const {error}=await sb.from('affiliates').update(row).eq('id',id);if(error)throw error;
   if(pass){const a=getAffiliate(id);if(!a||!a.userId)throw new Error('Affiliate ini belum punya akun login.');const r=await sb.rpc('admin_set_affiliate_password',{p_aff:id,p_password:pass});if(r.error)throw r.error}
   await adminLog('Affiliate diperbarui'+(pass?' (password diganti)':''),name+' ('+code+')')}
  else{
   const email=userToEmail(username);
   const tmp=window.supabase.createClient(CFG_URL,CFG_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});
   const {data,error}=await tmp.auth.signUp({email,password:pass});
   if(error)throw new Error(/registered|already/i.test(error.message)?'Username sudah dipakai.':error.message);
   if(!data.user||(data.user.identities&&data.user.identities.length===0))throw new Error('Username sudah dipakai.');
   const ins=await sb.from('affiliates').insert({...row,user_id:data.user.id,email,username});
   if(ins.error)throw new Error(ins.error.code==='23505'?'Kode atau username sudah digunakan.':ins.error.message);
   await adminLog('Affiliate dibuat',name+' ('+username+', '+code+')');
   if(!data.session)alert('Akun dibuat, tetapi Supabase masih meminta konfirmasi email sehingga affiliate belum bisa login. Matikan "Confirm email" di Supabase: Authentication > Sign In / Providers > Email (lihat README).')}
  $('affiliateModal').classList.remove('show');await refresh()}
 catch(err){st.style.color='var(--red)';st.textContent=err.message||String(err)}finally{btn.disabled=false}});
async function deleteAffiliate(id){const a=getAffiliate(id);if(!a)return;if(!confirm('Hapus affiliate '+a.name+'? Akun akan diarsipkan, transaksi dan riwayat komisi tetap disimpan.'))return;const {error}=await sb.from('affiliates').update({status:'deleted',deleted_at:new Date().toISOString(),code:'ARCHIVED-'+a.code+'-'+Date.now().toString().slice(-4)}).eq('id',id);if(error)return alert(error.message);await adminLog('Affiliate dihapus/diarsipkan',a.name);await refresh()}

/* --- Pesanan --- */
function renderOrdersAdmin(root){root.innerHTML=`<div class="panel-head"><div><h3>Pesanan pelanggan</h3><div class="muted">Pembayaran dikonfirmasi manual. Stok dipotong hanya setelah pembayaran dikonfirmasi dan stok tersedia.</div></div><span class="badge">${db.orders.length} pesanan</span></div>${db.orders.length?`<div class="table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Produk</th><th>Total</th><th>Sumber / bayar</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${db.orders.map(o=>{const a=getAffiliate(o.affiliateId);const cb=getAffiliate(o.claimedBy);return `<tr><td><strong>${esc(o.orderNo)}</strong><br><span class="muted">${new Date(o.createdAt).toLocaleString('id-ID')}</span></td><td>${esc(o.customerName)}<br><span class="muted">📞 ${esc(o.phone||'-')}</span><br><span class="muted">📍 ${esc(o.address||'-')}</span><br><span class="muted">${esc(o.note||'Tanpa catatan')}</span></td><td><div class="rowline" style="flex-wrap:nowrap;gap:8px">${orderThumb(o)}<div>${esc(o.productName)}<br><span class="muted">${esc(itemsText(o))}</span></div></div></td><td>${money(o.total)}</td><td>${o.source==='admin'?'<span class="badge green">Link admin</span>':a?esc(a.name)+' ('+esc(a.code)+')':o.affiliateCode?esc(o.affiliateCode):'Tanpa referral'}<br><span class="muted">Bayar: ${payLabel(o.paymentMethod)}</span></td><td>${badge(o.status)}${o.status==='payment_claimed'?'<br><small class="muted">Dikonfirmasi affiliate '+esc(cb?.name||'')+'</small>':''}${o.stockDeducted?'<br><small class="muted">Stok dipotong</small>':''}${o.adminNote?'<br><small class="muted">'+esc(o.adminNote)+'</small>':''}</td><td><div class="actions">${['awaiting_payment','payment_claimed'].includes(o.status)?`<button class="success" data-confirm="${o.id}">Konfirmasi bayar</button>${o.status==='payment_claimed'?`<button class="secondary" data-rejectclaim="${o.id}">Tolak klaim</button>`:''}<button class="danger" data-cancelorder="${o.id}">Batalkan</button>`:''}${o.status==='stock_issue'?`<button class="secondary" data-refund="${o.id}">Tandai refund selesai</button>`:''}${o.status==='paid'?`<button class="secondary" data-finish="${o.id}">Tandai selesai</button><button class="danger" data-return="${o.id}">Retur</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Belum ada pesanan. Buat pesanan dari katalog untuk mencoba alur.</div>'}`;
 const ord=id=>db.orders.find(x=>x.id===id);
 root.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=async()=>{const r=await call('admin_confirm_payment',{p_order_id:b.dataset.confirm});if(r.ok&&r.data==='stock_issue')alert('Stok tidak mencukupi. Konfirmasi ditolak dan pesanan ditandai untuk penyelesaian admin. Refund mungkin diperlukan.')});
 root.querySelectorAll('[data-rejectclaim]').forEach(b=>b.onclick=()=>{const r=prompt('Alasan menolak klaim pembayaran:','Pembayaran belum diterima');if(r===null)return;call('admin_reject_claim',{p_order_id:b.dataset.rejectclaim,p_reason:r})});
 root.querySelectorAll('[data-cancelorder]').forEach(b=>b.onclick=()=>{const o=ord(b.dataset.cancelorder);if(o&&confirm('Batalkan pesanan '+o.orderNo+'?'))call('admin_cancel_order',{p_order_id:o.id})});
 root.querySelectorAll('[data-refund]').forEach(b=>b.onclick=()=>call('admin_mark_refund_done',{p_order_id:b.dataset.refund}));
 root.querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>call('admin_complete_order',{p_order_id:b.dataset.finish}));
 root.querySelectorAll('[data-return]').forEach(b=>b.onclick=()=>{const o=ord(b.dataset.return);if(o&&confirm('Catat retur untuk '+o.orderNo+'?'))call('admin_return_order',{p_order_id:o.id})});
}

/* --- Komisi & transfer --- */
function balancePanelHtml(){const rows=db.affiliates.map(a=>({a,b:affBalance(a.id)})).filter(r=>r.b.ready||r.b.debt||r.b.paid||r.b.pending);
 return `<div class="panel"><div class="panel-head"><div><h3>Saldo affiliate &amp; transfer</h3><div class="muted">Admin bebas menentukan nominal transfer per affiliate, selama tidak melebihi saldo (komisi disetujui dikurangi koreksi). Nominal dialokasikan ke komisi tertua lebih dulu.</div></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Affiliate</th><th>Menunggu persetujuan</th><th>Disetujui</th><th>Koreksi</th><th>Saldo transfer</th><th>Sudah dibayar</th><th>Aksi</th></tr></thead><tbody>${rows.map(({a,b})=>`<tr><td><strong>${esc(a.name)}</strong><br><span class="muted">${esc(a.code)}</span></td><td>${money(b.pending)}</td><td>${money(b.ready)}</td><td>${b.debt?money(b.debt):'-'}</td><td><b>${money(b.balance)}</b></td><td>${money(b.paid)}</td><td><div class="actions"><button data-transfer="${a.id}" ${b.balance>0?'':'disabled'}>Transfer</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada saldo affiliate.</div>'}</div>`}
function renderCommissionsAdmin(root){const pending=db.commissions.filter(c=>c.status==='pending_review'),approved=db.commissions.filter(c=>c.status==='approved'),reversed=db.commissions.filter(c=>c.status==='reversed');root.innerHTML=`<div class="stats"><div class="stat"><div class="label">Menunggu persetujuan</div><div class="value">${money(pending.reduce((n,c)=>n+c.amount,0))}</div><div class="sub">${pending.length} komisi</div></div><div class="stat"><div class="label">Siap dibayar</div><div class="value">${money(approved.reduce((n,c)=>n+remainOf(c),0))}</div></div><div class="stat"><div class="label">Sudah dibayar</div><div class="value">${money(db.commissions.reduce((n,c)=>n+paidOf(c),0))}</div></div><div class="stat"><div class="label">Koreksi tercatat</div><div class="value">${money(reversed.reduce((n,c)=>n+(Number(c.correctionOutstanding)||0),0))}</div></div></div>${balancePanelHtml()}<div class="panel-head"><div><h3>Komisi affiliate</h3><div class="muted">Admin menyetujui komisi manual dan menandai transfer setelah benar-benar dibayar.</div></div></div>${db.commissions.length?`<div class="table-wrap"><table><thead><tr><th>Affiliate</th><th>Pesanan</th><th>Komisi</th><th>Status</th><th>Catatan</th><th>Aksi</th></tr></thead><tbody>${db.commissions.map(c=>{const a=getAffiliate(c.affiliateId);return `<tr><td>${esc(a?.name||'Affiliate diarsipkan')}<br><span class="muted">${esc(a?.code||'')}</span></td><td>${esc(c.orderNo||'-')}</td><td>${money(c.amount)}</td><td>${badge(c.status)}</td><td>${esc(c.note||'')}${c.status==='approved'&&paidOf(c)>0?'<br><span class="muted">Terbayar '+money(paidOf(c))+' dari '+money(c.amount)+'</span>':''}</td><td><div class="actions">${c.status==='pending_review'?`<button class="success" data-approvecom="${c.id}">Setujui</button><button class="danger" data-rejectcom="${c.id}">Tolak</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Belum ada komisi. Pesanan beratribusi affiliate akan membuat komisi tertunda setelah pembayaran dikonfirmasi.</div>'}`;
 root.querySelectorAll('[data-approvecom]').forEach(b=>b.onclick=()=>call('admin_set_commission',{p_commission_id:b.dataset.approvecom,p_approve:true,p_reason:''}));
 root.querySelectorAll('[data-rejectcom]').forEach(b=>b.onclick=()=>{const r=prompt('Alasan penolakan komisi:','Pesanan tidak memenuhi syarat');if(r===null)return;call('admin_set_commission',{p_commission_id:b.dataset.rejectcom,p_approve:false,p_reason:r})});
 root.querySelectorAll('[data-transfer]').forEach(b=>b.onclick=()=>openPayout(b.dataset.transfer));
}
function openPayout(id){const a=getAffiliate(id);if(!a)return;const b=affBalance(id);if(b.balance<=0)return;$('poAff').value=id;$('poNote').value='';$('poAmount').max=b.balance;$('poAmount').value=b.balance;$('poStatus').textContent='';
 $('poSummary').innerHTML=`<strong>${esc(a.name)} · ${esc(a.code)}</strong><div class="muted" style="margin-top:4px">Komisi disetujui ${money(b.ready)}${b.debt?' − koreksi '+money(b.debt):''}</div><div class="muted">Saldo bisa ditransfer</div><div class="big">${money(b.balance)}</div>`;$('payoutModal').classList.add('show')}
$('poAll').onclick=()=>{$('poAmount').value=affBalance($('poAff').value).balance};
$('poHalf').onclick=()=>{$('poAmount').value=Math.floor(affBalance($('poAff').value).balance/2)};
$('payoutForm').addEventListener('submit',async e=>{e.preventDefault();const id=$('poAff').value,b=affBalance(id),x=Math.round(Number($('poAmount').value)||0);if(x<=0){$('poStatus').textContent='Nominal harus lebih dari 0.';return}if(x>b.balance){$('poStatus').textContent='Nominal melebihi saldo ('+money(b.balance)+').';return}
 if(!confirm('Tandai transfer '+money(x)+' ke '+(getAffiliate(id)?.name||'affiliate')+' sebagai sudah dibayar?'+(b.debt?' Koreksi '+money(b.debt)+' akan dipotong dari saldo.':'')+' Pastikan transfer aktual sudah dilakukan.'))return;
 const r=await call('admin_payout',{p_aff:id,p_amount:x,p_note:$('poNote').value.trim()});if(r.ok)$('payoutModal').classList.remove('show')});

/* --- Pembayaran --- */
function renderPaymentsAdmin(root){const P=db.settings.payments;let img=P.qris.image||'';
 const prev=()=>{$('pqPrev').innerHTML=img?`<img src="${esc(img)}" alt="QRIS" style="width:220px;border:1px solid var(--line);border-radius:10px"><br><button type="button" class="danger" id="pqDel" style="margin-top:8px">Hapus gambar</button>`:'<div class="muted">Belum ada gambar QRIS.</div>';if($('pqDel'))$('pqDel').onclick=()=>{img='';prev()}};
 root.innerHTML=`<div class="panel-head"><div><h3>Metode pembayaran</h3><div class="muted">Aktifkan metode yang boleh dipilih pelanggan.</div></div></div>
 <div class="panel"><label class="payopt"><input type="checkbox" id="pqOn"> <b>QRIS</b></label><div class="field"><label>Gambar QRIS (unggah dari perangkat)</label><input type="file" id="pqFile" accept="image/*"></div><div id="pqPrev" style="margin-top:10px"></div></div>
 <div class="panel"><label class="payopt"><input type="checkbox" id="ptOn"> <b>Transfer bank</b></label><div class="form-grid"><div class="field"><label>Nama bank</label><input id="ptBank"></div><div class="field"><label>Nomor rekening</label><input id="ptNum" inputmode="numeric"></div><div class="field full"><label>Atas nama</label><input id="ptHolder"></div></div></div>
 <div class="panel"><label class="payopt"><input type="checkbox" id="pcOn"> <b>Tunai</b></label><div class="field"><label>Keterangan untuk pelanggan</label><textarea id="pcNote"></textarea></div></div>
 <button id="paySave">Simpan metode pembayaran</button> <span id="paySt" class="status"></span>`;
 $('pqOn').checked=P.qris.enabled;$('ptOn').checked=P.transfer.enabled;$('pcOn').checked=P.cash.enabled;$('ptBank').value=P.transfer.bank||'';$('ptNum').value=P.transfer.number||'';$('ptHolder').value=P.transfer.holder||'';$('pcNote').value=P.cash.note||'';prev();
 $('pqFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/'))return alert('Pilih file gambar.');try{img=await compressImage(f);prev()}catch(err){alert('Gagal memproses gambar.')}});
 $('paySave').onclick=async()=>{const st=$('paySt');st.style.color='var(--red)';const t={enabled:$('ptOn').checked,bank:$('ptBank').value.trim(),number:$('ptNum').value.trim(),holder:$('ptHolder').value.trim()};if(t.enabled&&!t.number){st.textContent='Isi nomor rekening untuk mengaktifkan transfer.';return}if($('pqOn').checked&&!img){st.textContent='Unggah gambar QRIS untuk mengaktifkan QRIS.';return}
  $('paySave').disabled=true;st.style.color='var(--green)';st.textContent='Menyimpan...';
  try{let qimg=img;if(qimg.startsWith('data:'))qimg=await uploadImage(qimg,'qris');const payments={qris:{enabled:$('pqOn').checked,image:qimg},transfer:t,cash:{enabled:$('pcOn').checked,note:$('pcNote').value.trim()}};const {error}=await sb.from('settings').update({payments}).eq('id',1);if(error)throw error;await adminLog('Metode pembayaran diperbarui','QRIS / transfer / tunai');await refresh();setTimeout(()=>{if($('paySt')){$('paySt').style.color='var(--green)';$('paySt').textContent='Tersimpan.'}},0)}
  catch(err){st.style.color='var(--red)';st.textContent='Gagal: '+(err.message||err)}finally{if($('paySave'))$('paySave').disabled=false}}}

/* --- Link penjualan admin --- */
function renderSalesLinkAdmin(root){const url=baseUrl()+'?sales=admin',list=db.orders.filter(o=>o.source==='admin'),tot=list.filter(o=>['paid','completed'].includes(o.status)).reduce((n,o)=>n+o.total,0);
 root.innerHTML=`<div class="panel-head"><div><h3>Link penjualan admin</h3><div class="muted">Bagikan link ini untuk penjualan oleh admin sendiri. Pesanan lewat link ini ditandai "Link admin" dan tidak menghasilkan komisi affiliate.</div></div></div><div class="inline"><input id="admLink" readonly value="${esc(url)}" style="flex:1;min-width:180px;padding:10px;border:1px solid var(--line);border-radius:9px"><button id="admCopy">Salin link</button></div><div class="stats" style="margin-top:16px"><div class="stat"><div class="label">Pesanan via link admin</div><div class="value">${list.length}</div></div><div class="stat"><div class="label">Sudah dibayar</div><div class="value">${money(tot)}</div></div></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Total</th><th>Bayar</th><th>Status</th></tr></thead><tbody>${list.map(o=>`<tr><td><div class="rowline" style="flex-wrap:nowrap;gap:8px">${orderThumb(o,40)}<div>${esc(o.orderNo)}<br><span class="muted">${esc(o.productName)}</span></div></div></td><td>${esc(o.customerName)}</td><td>${money(o.total)}</td><td>${payLabel(o.paymentMethod)}</td><td>${badge(o.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada pesanan lewat link admin.</div>'}`;
 $('admCopy').onclick=()=>copyText(url,'Link penjualan admin disalin.')}

/* --- Pengaturan --- */
function renderSettingsAdmin(root){root.innerHTML=`<h3>Pengaturan komisi dan program</h3><div class="form-grid"><div class="field"><label>Komisi default</label><select id="sMode"><option value="fixed">Nominal tetap per pcs (Rp)</option><option value="percent">Persentase harga produk (%)</option></select></div><div class="field"><label>Nilai default</label><input id="sValue" type="number" min="0"></div><div class="field"><label>Masa aktif affiliate (bulan)</label><input type="number" value="6" readonly><div class="muted">Ditetapkan 6 bulan.</div></div><div class="field full"><label>Catatan aturan atribusi</label><input value="Sesi browser saja; tidak berlaku lintas sesi" readonly></div><div class="field full"><button id="saveSettings">Simpan pengaturan</button> <span id="settingsStatus" class="status"></span></div></div><div class="notice" style="margin-top:16px">Komisi per affiliate diatur lewat menu Affiliate → Atur komisi. Urutan prioritas: komisi khusus affiliate → komisi produk → default. Perubahan tidak mengubah komisi pesanan lama.</div>
 <div class="panel" style="margin-top:16px"><h3>Ganti password admin</h3><div class="form-grid"><div class="field"><label>Password baru (min. 8 karakter)</label><input id="sNewPass" type="password" autocomplete="new-password"></div></div><button id="sPassBtn" style="margin-top:10px">Ganti password</button> <span id="sPassSt" class="status"></span></div>
 <div class="panel" style="margin-top:16px"><h3>Riwayat pembayaran komisi</h3>${db.payouts.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Affiliate</th><th>Komisi bruto</th><th>Koreksi</th><th>Ditransfer</th><th>Metode</th><th>Catatan</th></tr></thead><tbody>${db.payouts.map(p=>`<tr><td>${new Date(p.date).toLocaleString('id-ID')}</td><td>${esc(getAffiliate(p.affiliateId)?.name||'Affiliate diarsipkan')}</td><td>${money(p.amount)}</td><td>${money(p.correctionDeducted)}</td><td>${money(p.netAmount)}</td><td>${esc(p.method)}</td><td>${esc(p.note||'-')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada catatan pembayaran komisi.</div>'}</div>`;
 $('sMode').value=db.settings.commissionMode;$('sValue').value=db.settings.commissionValue;
 $('saveSettings').onclick=async()=>{const {error}=await sb.from('settings').update({commission_mode:$('sMode').value,commission_value:Math.max(0,Number($('sValue').value)||0)}).eq('id',1);if(error){$('settingsStatus').style.color='var(--red)';$('settingsStatus').textContent=error.message;return}await adminLog('Pengaturan diubah','Komisi default diperbarui');await refresh();if($('settingsStatus')){$('settingsStatus').style.color='var(--green)';$('settingsStatus').textContent='Pengaturan disimpan.'}};
 $('sPassBtn').onclick=async()=>{const pw=$('sNewPass').value,st=$('sPassSt');if(pw.length<8){st.style.color='var(--red)';st.textContent='Minimal 8 karakter.';return}const {error}=await sb.auth.updateUser({password:pw});st.style.color=error?'var(--red)':'var(--green)';st.textContent=error?error.message:'Password diganti.';if(!error)$('sNewPass').value=''}
}

/* ---------- Utilitas UI umum ---------- */
document.addEventListener('click',e=>{const z=e.target.closest&&e.target.closest('[data-zoom]');if(!z)return;$('imgBig').src=z.dataset.zoom;$('imgModal').classList.add('show')});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).classList.remove('show')));
document.querySelectorAll('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)o.classList.remove('show')}));
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay.show').forEach(o=>o.classList.remove('show'))});
function vGroupsHtml(p,cb){const order=[],map=Object.create(null);p.variants.forEach((x,i)=>{const g=(x.group||'').trim();if(!(g in map)){map[g]=[];order.push(g)}map[g].push(i)});const multi=order.length>1||order[0]!=='';const grid=g=>'<div class="vgrid">'+map[g].map(i=>cb(p.variants[i],i)).join('')+'</div>'+(map[g].length>6?'<div class="vhint">Geser ke samping untuk variasi lainnya ›</div>':'');if(!multi)return grid(order[0]);let act=0;try{const q=orderContext&&orderContext.qty;if(q){const f=order.findIndex(g=>map[g].some(i=>q[i]>0));if(f>=0)act=f}}catch(e){}return '<div class="vtabs">'+order.map((g,k)=>'<button type="button" class="vtab'+(k===act?' on':'')+'" data-vtab="'+k+'" data-items="'+map[g].join(',')+'">'+esc(g||'Lainnya')+'<span class="tbadge"></span></button>').join('')+'</div>'+order.map((g,k)=>'<div class="vpanel'+(k===act?' on':'')+'" data-vp="'+k+'">'+grid(g)+'</div>').join('')}
function refreshTabBadges(){document.querySelectorAll('#orderProductSummary [data-vtab]').forEach(b=>{const n=b.dataset.items.split(',').reduce((a,i)=>a+(orderContext.qty[i]||0),0);const t=b.querySelector('.tbadge');t.textContent=n;t.style.display=n?'inline-grid':'none'})}
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-vtab]');if(!t)return;const box=t.closest('#orderProductSummary');if(!box)return;box.querySelectorAll('[data-vtab]').forEach(b=>b.classList.toggle('on',b===t));box.querySelectorAll('[data-vp]').forEach(d=>d.classList.toggle('on',d.dataset.vp===t.dataset.vtab));try{t.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'})}catch(_){}});

/* ---------- Referral & start ---------- */
async function processReferralQuery(){const q=new URLSearchParams(location.search);const note=t=>{const n=document.createElement('div');n.className='notice';n.innerHTML=t;$('view-catalog').prepend(n)};
 if(q.get('sales')==='admin'){SS.setItem('kabauria_sales_admin','1');SS.removeItem('kabauria_referral_session');note('Anda berbelanja lewat <b>link penjualan admin</b> KABAURIA.');return}
 const ref=q.get('ref');if(!ref)return;const {data}=await sb.rpc('check_referral',{p_code:ref});
 if(data){SS.setItem('kabauria_referral_session',ref.trim().toUpperCase());SS.removeItem('kabauria_sales_admin');note('Referral aktif: <b>'+esc(ref.trim().toUpperCase())+'</b>. Berlaku pada sesi browser ini.')}}
async function init(){
 renderCatalog();
 if(!sb){$('setupNotice').innerHTML='<div class="notice"><b>Belum tersambung ke Supabase.</b> '+esc(cfgWhy)+'</div>';renderAdmin();return}
 try{await refreshRole()}catch(e){console.error(e)}
 await refresh();
 try{await processReferralQuery()}catch(e){console.error(e)}
}
init();
